import pathlib
import importlib.util
import random

def _load():
    me = pathlib.Path(__file__).resolve()
    cands = []
    for base in [pathlib.Path('.'), pathlib.Path('/tmp'), pathlib.Path('/workspace')]:
        if base.exists():
            cands.extend(base.glob('*.py'))
            cands.extend(base.glob('**/*.py'))
    for p in cands:
        try:
            if p.resolve() == me:
                continue
        except Exception:
            pass
        try:
            t = p.read_text()
        except Exception:
            continue
        if '_sample_length' in t and 'def generate_words' in t and '_load' not in t:
            try:
                spec = importlib.util.spec_from_file_location('target_mod', str(p))
                m = importlib.util.module_from_spec(spec)
                spec.loader.exec_module(m)
            except Exception:
                continue
            if hasattr(m, '_sample_length') and hasattr(m, 'generate_words'):
                return m
    raise ImportError('target module with _sample_length not found')

_target = _load()
_sample_length = _target._sample_length
generate_words = _target.generate_words

def test_sample_length_respects_bounds():
    rng = random.Random(42)
    for _ in range(500):
        v = _sample_length(rng, 5, 12)
        assert 5 <= v <= 12, f'_sample_length(5,12) returned {v}, violates contract [5,12]'

def test_sample_length_other_range():
    rng = random.Random(1)
    for _ in range(200):
        v = _sample_length(rng, 8, 15)
        assert 8 <= v <= 15, f'_sample_length(8,15) returned {v}'

def test_generate_words_respects_min_max():
    words = generate_words(n=2000, min_len=5, max_len=12, seed=42)
    bad = [w for w in words if not (5 <= len(w) <= 12)]
    assert not bad, f'{len(bad)}/2000 words out of range [5,12], e.g. {bad[:5]}'

def test_generate_words_diversity():
    words = generate_words(n=20000, min_len=5, max_len=12, seed=42)
    uniq = len(set(words))
    assert uniq > 10000, f'only {uniq} uniques in 20000 words len 5-12, expected mostly unique; generator collapsed to len 1-2'
